#!/usr/bin/env node
'use strict';

const path = require('path');
const http = require('http');

// ── Parse CLI args ────────────────────────────────────────────────────────────
const args = process.argv.slice(2);

if (args.includes('--help') || args.includes('-h')) {
  console.log(`
  APK Builder – Web to Android APK Converter

  Usage:
    apk-builder [options]

  Options:
    --port <n>   Port to listen on (default: 3000)
    --no-open    Don't open the browser automatically
    --help       Show this help message
    --version    Show version

  Examples:
    apk-builder
    apk-builder --port 8080
    apk-builder --no-open
  `);
  process.exit(0);
}

if (args.includes('--version') || args.includes('-v')) {
  const pkg = require('../package.json');
  console.log(pkg.version);
  process.exit(0);
}

const portArg = args.indexOf('--port');
if (portArg !== -1 && args[portArg + 1]) {
  process.env.PORT = args[portArg + 1];
}

const noOpen = args.includes('--no-open');

// ── Start the server ──────────────────────────────────────────────────────────
// We load server.js which calls server.listen() internally.
// Patch it slightly to hook the 'listening' event for auto-open.
const PORT = parseInt(process.env.PORT || '3000', 10);

// Monkey-patch http.Server.listen to intercept the ready event
const _listen = http.Server.prototype.listen;
http.Server.prototype.listen = function (...listenArgs) {
  const result = _listen.apply(this, listenArgs);
  this.once('listening', () => {
    const url = `http://localhost:${PORT}`;
    console.log('\n  ✅  APK Builder is running!');
    console.log(`  🌐  Open: ${url}\n`);
    if (!noOpen) openBrowser(url);
  });
  return result;
};

// Load the server (resolves relative to the package root)
require(path.join(__dirname, '..', 'server.js'));

// ── Open browser ──────────────────────────────────────────────────────────────
function openBrowser(url) {
  const { platform } = process;
  const { exec } = require('child_process');

  const cmd =
    platform === 'win32'  ? `start "" "${url}"` :
    platform === 'darwin' ? `open "${url}"` :
    `xdg-open "${url}"`;

  exec(cmd, (err) => {
    if (err) {
      // Non-fatal — user can just open the URL manually
    }
  });
}
